import{_ as t,o as e,c as a,ag as d}from"./chunks/framework.BwSLX4ak.js";const p=JSON.parse('{"title":"BiliMusicBridge","description":"","frontmatter":{},"headers":[],"relativePath":"bilimusicbridge/index.md","filePath":"bilimusicbridge/index.md"}'),l={name:"bilimusicbridge/index.md"};function s(o,i,r,c,n,h){return e(),a("div",null,[...i[0]||(i[0]=[d(`<h1 id="bilimusicbridge" tabindex="-1">BiliMusicBridge <a class="header-anchor" href="#bilimusicbridge" aria-label="Permalink to &quot;BiliMusicBridge&quot;">​</a></h1><p>BiliMusicBridge 把 B 站直播间中以“点歌”开头的弹幕交给 AllMusic 默认音乐源搜索，并将第一条搜索结果加入 AllMusic 队列。它支持 Bukkit、Folia、BungeeCord 和 Velocity，AllMusic 与桥接插件需要处于同一进程和平台。</p><h2 id="安装前准备" tabindex="-1">安装前准备 <a class="header-anchor" href="#安装前准备" aria-label="Permalink to &quot;安装前准备&quot;">​</a></h2><ul><li>对应平台的 AllMusic <strong>4.2.0 或更高版本</strong>。</li><li>至少一个可用的 AllMusic 音乐源，例如 <a href="./../allmusic/qqmusic.html">QQMusic</a> 或 <a href="./../allmusic/kugou.html">Kugou</a>，并设置好 <code>defaultApi</code>。</li><li>与 AllMusic 配套的客户端音乐模组，供玩家听到音乐。</li><li>直播间号，以及匹配运行平台的 <a href="https://github.com/hutuyee/BiliMusicBridge/releases" target="_blank" rel="noreferrer">BiliMusicBridge 安装包</a>。</li></ul><table tabindex="0"><thead><tr><th>运行平台</th><th>安装包</th><th>插件字节码要求</th></tr></thead><tbody><tr><td>Spigot / Paper / Purpur</td><td><code>BiliMusicBridge-Bukkit-*.jar</code></td><td>Java 8+</td></tr><tr><td>Folia</td><td><code>BiliMusicBridge-Folia-*.jar</code></td><td>Java 17+</td></tr><tr><td>BungeeCord / Waterfall</td><td><code>BiliMusicBridge-BungeeCord-*.jar</code></td><td>Java 8+</td></tr><tr><td>Velocity</td><td><code>BiliMusicBridge-Velocity-*.jar</code></td><td>Java 11+</td></tr></tbody></table><p>服务端、代理和 AllMusic 自身的 Java 要求也需要满足。Folia 使用专用包；一个实例只放入一个平台包。</p><h2 id="第一次连接" tabindex="-1">第一次连接 <a class="header-anchor" href="#第一次连接" aria-label="Permalink to &quot;第一次连接&quot;">​</a></h2><ol><li>先安装 AllMusic 与音乐源，在游戏里确认自己的点歌配置可用。</li><li>将 BiliMusicBridge 平台包放入 <code>plugins/</code>，启动生成配置。</li><li>在插件数据目录的 <code>config.yml</code> 填写直播间号：</li></ol><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">room-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto-connect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cookie-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cookie.json&quot;</span></span></code></pre></div><ol start="4"><li>执行 <code>/bilimusic reload</code>，再用 <code>/bilimusic status</code> 查看状态。</li><li>直播间发送 <code>点歌 晴天</code>。默认要求游戏中存在可播放玩家。</li></ol><p>默认也识别 <code>点歌晴天</code>、<code>点歌：晴天</code>、<code>点歌: 晴天</code> 和 <code>点歌 - 晴天</code>。插件使用 AllMusic 默认音乐源的第一条结果，直播观众无需提供 Minecraft 账号。</p><h2 id="日常管理" tabindex="-1">日常管理 <a class="header-anchor" href="#日常管理" aria-label="Permalink to &quot;日常管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/bilimusic status</code></td><td>查看连接与插件状态</td></tr><tr><td><code>/bilimusic reconnect</code></td><td>重新连接直播间</td></tr><tr><td><code>/bilimusic request &lt;歌曲名&gt;</code></td><td>管理员直接提交一次点歌请求</td></tr><tr><td><code>/bilimusic reload</code></td><td>重新读取配置</td></tr></tbody></table><p>命令别名为 <code>/bmb</code>，权限为 <code>bilimusic.admin</code>。</p><p>限流、Cookie、显示名称、队列规则和配置示例见<a href="./reference.html">完整手册</a>，无法连接或点歌失败时见<a href="./troubleshooting.html">常见问题</a>。</p>`,15)])])}const g=t(l,[["render",s]]);export{p as __pageData,g as default};
